// FleetScanHostOutcome represents where one host of a fleet scan lands in the outcome model, for filtering FleetScan.hostsConnection. A host's outcome is its status plus its reason: a host the scan never reached (reason OFFLINE, NOT_REACHED or IME_NOT_RESPONDING) or could not tell it reached (reason START_UNKNOWN) is not assessed whatever status carries it.
type FleetScanHostOutcome string

// Where one host of a fleet scan lands in the outcome model, for filtering FleetScan.hostsConnection. A host's outcome is its status plus its reason: a host the scan never reached (reason OFFLINE, NOT_REACHED or IME_NOT_RESPONDING) or could not tell it reached (reason START_UNKNOWN) is not assessed whatever status carries it.
const (
	FleetScanHostOutcomeSucceeded   FleetScanHostOutcome = "SUCCEEDED"    // The scan ran on the host (status SUCCESS).
	FleetScanHostOutcomeNotAssessed FleetScanHostOutcome = "NOT_ASSESSED" // The scan did not reach the host: reason OFFLINE, NOT_REACHED, IME_NOT_RESPONDING or START_UNKNOWN, or still PENDING once the scan has ended. Counted in FleetScan.notAssessedHosts.
	FleetScanHostOutcomeFailed      FleetScanHostOutcome = "FAILED"       // The scan reached the host and something broke: ERROR or TIMEOUT, not unreached. Counted in FleetScan.failedHosts.
	FleetScanHostOutcomeNotEligible FleetScanHostOutcome = "NOT_ELIGIBLE" // The scan could never run on the host: SKIPPED, not unreached. Counted in FleetScan.skippedHosts.
	FleetScanHostOutcomePending     FleetScanHostOutcome = "PENDING"      // The host has not reported yet and the scan is still running.
)

// FleetScanHostReason represents why a fleet-scan host has its terminal or not-reached status: the structured category behind `FleetScanHost.detail`, for filtering and counting hosts by why they did not scan. Clients must tolerate values added later.
type FleetScanHostReason string

// Why a fleet-scan host has its terminal or not-reached status: the structured category behind `FleetScanHost.detail`, for filtering and counting hosts by why they did not scan. Clients must tolerate values added later.
const (
	FleetScanHostReasonNotManaged          FleetScanHostReason = "NOT_MANAGED"          // In the target group, but not managed by the management system.
	FleetScanHostReasonNotReached          FleetScanHostReason = "NOT_REACHED"          // The device had not run the scan by the scan deadline.
	FleetScanHostReasonOffline             FleetScanHostReason = "OFFLINE"              // The device was not reachable when the scan started: its management system reported it offline, or it had not checked in for longer than the offline threshold. The scan did not wait for it; the next scan tries it again.
	FleetScanHostReasonTriggerFailed       FleetScanHostReason = "TRIGGER_FAILED"       // The management system did not accept the run for this device.
	FleetScanHostReasonAuthRefused         FleetScanHostReason = "AUTH_REFUSED"         // The device could not authenticate to Mondoo (exit code 77).
	FleetScanHostReasonDownloadFailed      FleetScanHostReason = "DOWNLOAD_FAILED"      // No binary source produced a verified cnspec (exit code 75).
	FleetScanHostReasonProviderUnavailable FleetScanHostReason = "PROVIDER_UNAVAILABLE" // A pinned cnspec provider could not be installed (exit code 76).
	FleetScanHostReasonPrivateDirRefused   FleetScanHostReason = "PRIVATE_DIR_REFUSED"  // A directory the run must own could not be made private (exit code 78).
	FleetScanHostReasonBudgetExceeded      FleetScanHostReason = "BUDGET_EXCEEDED"      // The device-wide time budget ran out (exit code 79).
	FleetScanHostReasonTimeout             FleetScanHostReason = "TIMEOUT"              // cnspec did not finish within its timeout (exit code 124).
	FleetScanHostReasonCnspecFailed        FleetScanHostReason = "CNSPEC_FAILED"        // cnspec ran and failed.
	FleetScanHostReasonUploadFailed        FleetScanHostReason = "UPLOAD_FAILED"        // The scan ran, but its results could not be uploaded.
	FleetScanHostReasonBootstrapError      FleetScanHostReason = "BOOTSTRAP_ERROR"      // The bootstrap itself failed (bad manifest, auth setup).
	FleetScanHostReasonImeNotResponding    FleetScanHostReason = "IME_NOT_RESPONDING"   // The device checked in after the sync request, but the Intune Management Extension did not pick up the scan's script within the grace period.
	FleetScanHostReasonNotCheckingIn       FleetScanHostReason = "NOT_CHECKING_IN"      // MDM check-in did not move after the sync request. Set on a host that is still pending: the device's Intune Management Extension can still run the scan, so the scan keeps waiting for it.
	FleetScanHostReasonStartUnknown        FleetScanHostReason = "START_UNKNOWN"        // The server dispatching the scan stopped while it sent the scan to this device, so whether the scan reached the device is unknown, and no result arrived before the scan's time ran out. Not assessed, not failed; the next scan tries the device again.
	FleetScanHostReasonNoResult            FleetScanHostReason = "NO_RESULT"            // The management system started the run on the device, but returned no result to read (no task to follow, or a task that could not be read). Failed; what happened on the device is unknown.
	FleetScanHostReasonPolicyRefused       FleetScanHostReason = "POLICY_REFUSED"       // The management system's policy for the device refused the run (CrowdStrike: the RTR Response Policy does not allow custom scripts). Failed; fix the policy in the management system.
)

